/* Seiko Alpinist Archive — index page interactions. Data: window.ALP (generated by tools/build.py). */
(function(){
const D=window.ALP,$=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const U='<span class="unk">Unknown</span>';
const v=(x,suf='')=>x===null||x===undefined||x===''?U:esc(x)+suf;
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const byId=Object.fromEntries(D.models.map(m=>[m.id,m]));
const statusTag=m=>m.status==='current'?'<span class="tag cur">Current</span>':m.status==='limited'?'<span class="tag lim">Limited</span>':'<span class="tag dis">Discontinued</span>';
const page=m=>`watches/${m.id}.html`;
function imgHTML(m,cls){
  if(m.img)return `<img class="${m.img.hotlink&&m.img.transparent!==false?'cut':'ph'}" src="${esc(m.img.thumb||m.img.src)}" alt="${esc(m.img.alt||m.name)}" loading="lazy" decoding="async" ${m.img.hotlink?'referrerpolicy="no-referrer" onerror="this.replaceWith(Object.assign(document.createElement(\'div\'),{className:\'noimg\',innerHTML:window.renderWatch(window.ALP_SCHEM[\''+m.id+'\']||{})+\'<br>Schematic — official photo unavailable\'}))"':''}>`;
  return `<div class="noimg">${window.renderWatch(m.schem||{},{aria:'Schematic illustration of '+esc(m.name)})}<span>Schematic illustration · no licensed photo</span></div>`;
}
window.ALP_SCHEM=Object.fromEntries(D.models.map(m=>[m.id,m.schem||{}]));

/* nav + altimeter */
const nav=$('.nav');
const onScroll=()=>{
  nav.classList.toggle('solid',scrollY>40);
  const h=document.documentElement.scrollHeight-innerHeight,p=Math.min(1,scrollY/h);
  const dot=$('.altimeter .dot');if(dot)dot.style.top=(100-p*100)+'%';
  const val=$('.altimeter b');if(val)val.textContent=Math.round(p*3776).toLocaleString()+'m';
  const bg=$('.hero .bg');if(bg&&!reduce&&scrollY<innerHeight*1.2)bg.style.transform=`translate3d(0,${scrollY*.25}px,0)`;
};
addEventListener('scroll',onScroll,{passive:true});onScroll();
$('.menu-btn')?.addEventListener('click',e=>{const u=$('.nav ul');const o=u.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',o);});
$$('.nav ul a').forEach(a=>a.addEventListener('click',()=>$('.nav ul').classList.remove('open')));
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}}),{rootMargin:'0px 0px -8% 0px'});
$$('.rv').forEach(el=>io.observe(el));
const secIO=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){$$('.nav ul a').forEach(a=>a.toggleAttribute('aria-current',a.getAttribute('href')==='#'+e.target.id));}}),{rootMargin:'-45% 0px -50% 0px'});
$$('main > section[id]').forEach(s=>secIO.observe(s));

/* ---------- MAP ---------- */
(function(){
  const M=window.MAPDATA,svg=$('#map-svg');if(!svg||!M)return;
  const NS='http://www.w3.org/2000/svg';
  const proj=(lon,lat)=>[(lon-M.proj.lon0)*M.proj.c*M.proj.s,(M.proj.lat0-lat)*M.proj.s];
  let s=`<g class="grat">`;for(let lo=130;lo<=146;lo+=2){const[x]=proj(lo,0);s+=`<line x1="${x}" y1="0" x2="${x}" y2="${M.h}"/>`;}for(let la=32;la<=46;la+=2){const[,y]=proj(0,la);s+=`<line x1="0" y1="${y}" x2="${M.w}" y2="${y}"/>`;}s+='</g>';
  s+=`<path class="land" d="${M.land}"/>`;
  M.contours.forEach((d,i)=>s+=`<path class="ct${i%3===2?' m':''}" d="${d}"/>`);
  // compass rose
  s+=`<g transform="translate(70 90)" stroke="#efe8d6" fill="none" opacity=".6"><circle r="34"/><circle r="26" stroke-dasharray="1 3"/><path d="M0 -44 L5 0 L0 44 L-5 0Z" fill="#efe8d6" fill-opacity=".15"/><path d="M0 -44 L5 0 L-5 0Z" fill="#b3302b" stroke="none"/><text y="-50" text-anchor="middle" fill="#efe8d6" stroke="none" font-family="IBM Plex Mono" font-size="9">N</text></g>`;
  s+=`<g id="pins"></g>`;
  svg.innerHTML=s;
  const pins=$('#pins'),card=$('#map-card'),list=$('#map-list');
  D.mountains.forEach((m,i)=>{
    const[x,y]=proj(m.lon,m.lat);
    const g=document.createElementNS(NS,'g');g.setAttribute('class','pin');g.setAttribute('tabindex','0');g.setAttribute('role','button');
    g.setAttribute('aria-label',`${m.name}, ${m.elev?m.elev.toLocaleString()+' metres':'elevation unknown'}`);
    g.setAttribute('transform',`translate(${x} ${y})`);g.dataset.i=i;
    const lx=m.labelDx??8,ly=m.labelDy??3;
    g.innerHTML=`<circle class="hit" r="12"/><circle class="pulse" r="6"/><path class="tri" d="M0 -6 L5 3.5 L-5 3.5Z"/><text x="${lx}" y="${ly}" ${lx<0?'text-anchor="end"':''}>${esc(m.short||m.name)}</text>`;
    pins.appendChild(g);
    const b=document.createElement('button');b.textContent=m.short||m.name;b.setAttribute('aria-pressed','false');b.onclick=()=>show(i,true);list.appendChild(b);
    g.addEventListener('click',()=>show(i,true));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show(i,true);}});
    g.addEventListener('mouseenter',()=>show(i));g.addEventListener('focus',()=>show(i));
  });
  function show(i,zoom){
    const m=D.mountains[i];
    $$('.pin',svg).forEach(p=>p.classList.toggle('on',+p.dataset.i===i));
    $$('button',list).forEach((b,k)=>b.setAttribute('aria-pressed',k===i));
    card.innerHTML=`<div class="ph">${m.img?`<img src="${esc(m.img.src)}" alt="${esc(m.img.alt)}" loading="lazy">`:`<div class="noimg" style="height:100%;display:grid;place-items:center">${ico('mountain','lg')}<br>No licensed photograph located</div>`}</div>
    <div class="bd"><div class="mono" style="color:var(--gold)">${esc(m.jp)} · ${esc(m.romaji||'')}</div><h3>${esc(m.name)}</h3>
    <div class="el">${m.elev?m.elev.toLocaleString()+'<small style="font-size:.4em"> m</small>':U}</div>
    <dl><dt>Region</dt><dd>${v(m.pref)}</dd><dt>Range</dt><dd>${v(m.range)}</dd></dl>
    <ul>${m.facts.map(f=>`<li><span class="badge ${f.seiko?'sk':'ctx'}">${f.seiko?'Seiko-documented':'Japanese context'}</span>${esc(f.text)} <a href="${esc(f.src)}" target="_blank" rel="noopener" class="mono" style="font-size:.6rem">source ↗</a></li>`).join('')}</ul>
    ${m.img?`<p class="credit" style="text-align:left">Photo: ${esc(m.img.credit)} · <a href="${esc(m.img.source)}" target="_blank" rel="noopener">${esc(m.img.license)}</a></p>`:''}</div>`;
    if(zoom)zoomTo(m);
  }
  let vb=[0,0,M.w,M.h];
  function anim(to){
    if(reduce){vb=to;svg.setAttribute('viewBox',to.join(' '));return;}
    const from=vb.slice(),t0=performance.now();
    (function f(t){const k=Math.min(1,(t-t0)/900),e=1-Math.pow(1-k,3);vb=from.map((a,i)=>a+(to[i]-a)*e);svg.setAttribute('viewBox',vb.join(' '));if(k<1)requestAnimationFrame(f);})(t0);
  }
  function zoomTo(m){const[x,y]=proj(m.lon,m.lat);const w=M.w/4.2,h=M.h/4.2;anim([x-w/2,y-h/2,w,h]);setZoomBtns('alps');}
  function setZoomBtns(k){$$('.map-ctl button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.z===k));}
  $$('.map-ctl button').forEach(b=>b.addEventListener('click',()=>{
    if(b.dataset.z==='japan')anim([0,0,M.w,M.h]);
    else{const[x,y]=proj(137.9,36.1);const w=M.w/3,h=M.h/3;anim([x-w/2,y-h/2,w,h]);}
    setZoomBtns(b.dataset.z);
  }));
  show(0);
})();

/* ---------- TIMELINE (series-grouped) ---------- */
(function(){
  const tl=$('#tl-list');if(!tl)return;
  tl.innerHTML=D.series.filter(s=>s.members.length).map(s=>{
    const lead=byId[s.lead]||byId[s.members[0]];
    const m=lead;
    const specs=[
      ['movement','Movement',m.mv.cal?`Cal. ${m.mv.cal}`:null],
      [m.mv.type==='quartz'?'quartz':m.mv.type==='automatic'?'automatic':'manual','Type',m.mv.typeLabel],
      ['dia','Diameter',m.cs.dia?m.cs.dia+' mm':null],
      ['thick','Thickness',m.cs.thick?m.cs.thick+' mm':null],
      ['water','Water res.',m.cs.wr&&m.cs.wr.split(/;|\(/)[0].trim().slice(0,48)],
      [m.cs.crystalKind,'Crystal',m.cs.crystal],
      ['power','Power reserve',m.mv.pr?m.mv.pr+' h':null],
      ['compassbezel','Compass',m.compass.has?(m.compass.type||'Yes'):'None'],
      [m.jpOnly?'jp':'global','Market',m.market],
    ];
    return `<article class="tl-item rv" id="tl-${esc(s.id)}">
      <div class="tl-y"><b>${s.year??'—'}</b><span>${esc(s.era||'')}</span></div>
      <div class="tl-card">
        <div class="im">${imgHTML(m)}${m.img?`<p class="credit">${esc(m.img.credit)}</p>`:''}</div>
        <div class="tx">
          <div class="mono" style="color:var(--gold)">${esc(s.kicker||'')}</div>
          <h3>${esc(s.name)}</h3>
          <div class="rf">${s.members.map(id=>esc(byId[id].refs.primary)).join(' · ')}</div>
          <p>${esc(s.blurb||'')}</p>
          <div class="specs">${specs.map(([i,l,val])=>`<div class="spec">${ico(i)}<div><small>${l}</small>${v(val)}</div></div>`).join('')}</div>
          ${s.dispute?`<p class="disp">⚠ ${esc(s.dispute)}</p>`:''}
          <div class="acts">${s.members.slice(0,6).map(id=>`<a class="btn sm dk" href="${page(byId[id])}">${esc(byId[id].refs.primary)} →</a>`).join('')}</div>
        </div>
      </div></article>`;
  }).join('');
  $$('.rv',tl).forEach(el=>io.observe(el));
})();

/* ---------- MOVEMENTS ---------- */
(function(){
  const ch=$('#mv-chain');if(!ch)return;
  ch.innerHTML=D.movements.map(c=>`<div class="mv-node rv">${c.img?`<figure class="mv-ph"><img src="${esc(c.img.src)}" alt="${esc(c.img.alt)}" loading="lazy" referrerpolicy="no-referrer"><figcaption>${esc(c.img.credit)}</figcaption></figure>`:''}<div class="era">${esc(c.era||'')}</div><h4>${esc(c.cal)}</h4>
  <ul>${[['Type',c.type],['Jewels',c.jewels],['Beat',c.bph?c.bph.toLocaleString()+' vph':null],['Power reserve',c.pr?c.pr+' h':null],['Hacking',c.hack===true?'Yes':c.hack===false?'No':null],['Hand-winding',c.wind===true?'Yes':c.wind===false?'No':null],['Accuracy',c.acc]].map(([k,x])=>`<li><span>${k}</span><span>${v(x)}</span></li>`).join('')}</ul>
  <p class="chg">${esc(c.change||'')}</p><a class="mono" style="font-size:.6rem;color:var(--gold)" href="${esc(c.cc)}" target="_blank" rel="noopener">${/seiko-caliber-/.test(c.cc)?'Calibre '+esc(c.cal)+' on Caliber Corner':'Seiko calibres on Caliber Corner'} ↗</a></div>`).join('');
  $$('.rv',ch).forEach(el=>io.observe(el));
  // diagram parts
  const parts=$$('.mv-parts button'),svg=$('#mv-svg');
  parts.forEach(b=>b.addEventListener('click',()=>{
    const on=b.getAttribute('aria-pressed')!=='true';
    parts.forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed',on);
    $$('.part',svg).forEach(p=>p.classList.toggle('on',on&&p.dataset.part===b.dataset.part));
    $('.rotor',svg).style.transform=on&&b.dataset.part==='rotor'?'rotate(160deg)':on?'rotate(-35deg)':'none';
  }));
  $$('.part',svg).forEach(p=>{p.setAttribute('tabindex','0');p.addEventListener('click',()=>{const b=parts.find(x=>x.dataset.part===p.dataset.part);b&&b.click();});p.addEventListener('keydown',e=>{if(e.key==='Enter')p.dispatchEvent(new Event('click'));});});
})();

/* ---------- DESIGN EVOLUTION ---------- */
(function(){
  const st=$('#evo-stage');if(!st)return;
  const E=D.evolution,rng=$('#evo-range');rng.max=E.length-1;
  $('#evo-ticks').innerHTML=E.map(e=>`<span>${e.year}</span>`).join('');
  const rows=['case','hands','dial','indices','compass','crown','logo','caseback','movement'];
  function set(i){
    const e=E[i];
    st.querySelector('.svgh').innerHTML=window.renderWatch(e.cfg,{aria:`Schematic of ${e.name}`});
    $('#evo-yr').textContent=e.year;$('#evo-name').textContent=e.name;
    $('#evo-tab').innerHTML=rows.map(r=>{const prev=i>0?E[i-1].rows[r]:null,cur=e.rows[r];const ch=prev!==null&&prev!==cur;return `<tr><th>${r}</th><td style="${ch?'color:var(--gold)':''}">${cur?esc(cur):U}${ch?' <span class="mono" style="font-size:.55rem">· changed</span>':''}</td></tr>`;}).join('');
    rng.setAttribute('aria-valuetext',`${e.year} — ${e.name}`);
  }
  rng.addEventListener('input',()=>set(+rng.value));set(0);
})();

/* ---------- FAMILY TREE ---------- */
(function(){
  const host=$('#tree');if(!host)return;
  const T=D.tree,W=1180,colW=W/T.cols,rowH=66,H=T.rows*rowH+40;
  const pos=Object.fromEntries(T.nodes.map(n=>[n.id,[40+n.col*colW+colW/2-0,30+n.row*rowH]]));
  let s=`<svg viewBox="0 0 ${W+80} ${H}" role="img" aria-labelledby="tree-t"><title id="tree-t">Alpinist family tree</title>`;
  // era bands
  T.eras.forEach(e=>{s+=`<text x="10" y="${30+e.row*rowH+4}" style="font-size:9px;fill:var(--steel-d)">${esc(e.label)}</text>`;});
  T.edges.forEach(([a,b,kind])=>{const[x1,y1]=pos[a],[x2,y2]=pos[b];const my=(y1+y2)/2;s+=`<path class="ed${kind==='revival'?' dash':''}" d="M${x1} ${y1+17} C${x1} ${my} ${x2} ${my} ${x2} ${y2-17}"/>`;});
  T.nodes.forEach(n=>{const[x,y]=pos[n.id],w=Math.max(120,n.label.length*7.2+24);
    s+=`<a href="${n.href}" class="nd" aria-label="${esc(n.label)} ${esc(n.sub||'')}"><g><rect x="${x-w/2}" y="${y-17}" width="${w}" height="34" rx="2"/><text x="${x}" y="${y-2}" text-anchor="middle">${esc(n.label)}</text><text x="${x}" y="${y+11}" text-anchor="middle" style="font-size:9px;opacity:.65">${esc(n.sub||'')}</text></g></a>`;});
  host.innerHTML=s+'</svg>';
})();

/* ---------- EXPLORER ---------- */
const sel=new Set();
(function(){
  const fHost=$('#filters'),cards=$('#cards'),cnt=$('#count');if(!fHost)return;
  const F=[
    ['decade','Decade',m=>m.decade],
    ['series','Series / generation',m=>m.seriesName],
    ['mvType','Movement',m=>m.mv.typeLabel],
    ['color','Dial colour',m=>m.colorKey],
    ['size','Case size',m=>m.sizeBand],
    ['market','Market',m=>m.jpOnly===true?'Japan-only':m.jpOnly===false?'International release':'Unknown'],
    ['status','Status',m=>m.status==='current'?'Current production':m.status==='limited'?'Limited edition':'Discontinued'],
    ['feat','Features',m=>[m.gmt&&'GMT',m.compass.has&&'Compass ring',m.prospex&&'Prospex',m.historical&&'Laurel / historical'].filter(Boolean)],
  ];
  const opts={};
  F.forEach(([k,,fn])=>{const set=new Set();D.models.forEach(m=>[].concat(fn(m)).forEach(x=>x&&set.add(x)));opts[k]=[...set].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true}));});
  fHost.innerHTML=F.map(([k,l])=>`<fieldset class="fgroup"><legend>${l}</legend>${opts[k].map(o=>`<label class="chip"><input type="checkbox" data-k="${k}" value="${esc(o)}"><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('')+`<button class="reset" type="button">Reset filters</button>`;
  const active=()=>{const a={};$$('input:checked',fHost).forEach(i=>(a[i.dataset.k]??=new Set()).add(i.value));return a;};
  function render(){
    const a=active();
    const list=D.models.filter(m=>F.every(([k,,fn])=>!a[k]||[].concat(fn(m)).some(x=>a[k].has(String(x)))));
    cnt.textContent=`${list.length} of ${D.models.length} references`;
    cards.innerHTML=list.map(m=>`<a class="card" href="${page(m)}">
      <button class="cmp-add" type="button" data-cmp="${m.id}" aria-pressed="${sel.has(m.id)}" aria-label="Add ${esc(m.refs.primary)} to comparison">${sel.has(m.id)?'✓ Compare':'+ Compare'}</button>
      <div class="im">${imgHTML(m)}</div>
      <div class="bd"><div class="rf">${esc(m.refs.primary)}</div><div class="nm">${esc(m.nickname?'“'+m.nickname+'” · ':'')}${esc(m.seriesName)}</div>
      <div class="mt"><span>${m.year??'Year unknown'}</span><span>${m.mv.cal?'Cal. '+esc(m.mv.cal):'Cal. unknown'}</span><span>${esc(m.colorKey)}</span></div>
      <div class="st">${statusTag(m)}${m.limited.qty?`<span class="mono" style="font-size:.6rem">${m.limited.qty.toLocaleString()} pcs</span>`:''}</div></div></a>`).join('')||'<p>No references match these filters.</p>';
  }
  fHost.addEventListener('change',render);
  $('.reset',fHost).onclick=()=>{$$('input',fHost).forEach(i=>i.checked=false);render();};
  $('.filter-toggle')?.addEventListener('click',e=>{const o=fHost.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',o);});
  cards.addEventListener('click',e=>{const b=e.target.closest('[data-cmp]');if(!b)return;e.preventDefault();toggleCmp(b.dataset.cmp);render();});
  render();
})();

/* ---------- COMPARE ---------- */
function toggleCmp(id){window.__cmpTouched=true;
  if(sel.has(id))sel.delete(id);else{if(sel.size>=4){alert('Compare up to four references at a time.');return;}sel.add(id);}
  renderCmp();
}
function renderCmp(){
  const host=$('#cmp-table');if(!host)return;
  const ids=[...sel],ms=ids.map(i=>byId[i]);
  $$('.cmp-pick select').forEach((s,k)=>s.value=ids[k]||'');
  const tray=$('.tray');tray.classList.toggle('on',!!(ids.length>0&&window.__cmpTouched));$('.tray .mono').textContent=`${ids.length} selected for comparison`;
  if(ms.length<2){host.innerHTML=`<p style="padding:20px">Select at least two references above, or use “+ Compare” on any card in Models.</p>`;return;}
  const R=[
    ['Year',m=>m.year],['Series',m=>m.seriesName],['Movement',m=>m.mv.cal?`${m.mv.cal} (${m.mv.typeLabel})`:null],
    ['Diameter',m=>m.cs.dia?m.cs.dia+' mm':null],['Thickness',m=>m.cs.thick?m.cs.thick+' mm':null],['Lug-to-lug',m=>m.cs.l2l?m.cs.l2l+' mm':null],
    ['Power reserve',m=>m.mv.pr?m.mv.pr+' h':null],['Crystal',m=>m.cs.crystal],['Water resistance',m=>m.cs.wr],
    ['Compass',m=>m.compass.has?(m.compass.type||'Yes'):'None'],['GMT',m=>m.gmt?'Yes':'No'],['Status',m=>m.statusLabel],
    ['Limited quantity',m=>m.limited.qty?m.limited.qty.toLocaleString():(m.limited.is?'Quantity unconfirmed':'—')],
    ['Market',m=>m.market],['Dial',m=>m.dials.join(', ')||null],['Launch price',m=>m.msrpLabel],
  ];
  host.innerHTML=`<table class="cmp-table"><caption class="vh">Side-by-side comparison of ${ms.map(m=>m.refs.primary).join(', ')}</caption>
  <thead><tr><td></td>${ms.map(m=>`<th scope="col" class="hd">${imgHTML(m)}<a href="${page(m)}" class="mono" style="font-size:.8rem">${esc(m.refs.primary)}</a><br><button class="rm" data-rm="${m.id}">Remove</button></th>`).join('')}</tr></thead>
  <tbody>${R.map(([l,fn])=>{const vals=ms.map(fn).map(x=>x===null||x===undefined||x===''?null:String(x));const diff=new Set(vals).size>1;return `<tr><th scope="row">${l}</th>${vals.map(x=>`<td class="${diff?'diff':''}">${x===null?U:esc(x)}</td>`).join('')}</tr>`;}).join('')}</tbody></table>`;
}
(function(){
  const pick=$('.cmp-pick');if(!pick)return;
  const opts=`<option value="">— choose reference —</option>`+D.series.map(s=>`<optgroup label="${esc(s.name)}">${s.members.map(id=>`<option value="${id}">${esc(byId[id].refs.primary)}${byId[id].nickname?' “'+esc(byId[id].nickname)+'”':''}</option>`).join('')}</optgroup>`).join('');
  pick.innerHTML=[0,1,2,3].map(k=>`<label><span class="vh">Reference ${k+1}</span><select data-slot="${k}">${opts}</select></label>`).join('');
  pick.addEventListener('change',e=>{const ids=$$('select',pick).map(s=>s.value).filter(Boolean);sel.clear();[...new Set(ids)].forEach(i=>sel.add(i));renderCmp();document.dispatchEvent(new Event('cmpchange'));});
  $('#cmp-table').addEventListener('click',e=>{const b=e.target.closest('[data-rm]');if(b){sel.delete(b.dataset.rm);renderCmp();}});
  // sensible default comparison to demonstrate the tool
  (D.compareDefault||[]).forEach(i=>byId[i]&&sel.add(i));renderCmp();
})();

/* ---------- ARCHIVE ---------- */
(function(){
  const l=$('#arch-list');if(!l||!D.archive.length)return;
  l.innerHTML=D.archive.map((a,i)=>`<li><button aria-pressed="${i===0}" data-i="${i}">${esc(a.title)}<small>${esc(a.kind)} · ${esc(a.date||'date unknown')}</small></button></li>`).join('');
  const show=i=>{const a=D.archive[i];$$('button',l).forEach(b=>b.setAttribute('aria-pressed',+b.dataset.i===i));
    $('#arch-view').innerHTML=`<img src="${esc(a.src)}" alt="${esc(a.alt)}" loading="lazy" ${a.hotlink?'referrerpolicy="no-referrer"':''}>`;
    $('#arch-cap').innerHTML=`${esc(a.caption||'')}<br><span class="mono" style="font-size:.6rem">${esc(a.credit)} · <a href="${esc(a.source)}" target="_blank" rel="noopener">source ↗</a>${a.license?' · '+esc(a.license):''}</span>`;};
  l.addEventListener('click',e=>{const b=e.target.closest('button');b&&show(+b.dataset.i);});show(0);
})();
})();
